    for scale, anchors in scale_groups.items():
        # Find which target anchor corresponds to the main template anchor
        # We can just check all possible subsets, but since anchors are exactly transformed, 
        # we can just use the top-left most in each connected group of anchors.
        # Simple heuristic: group target anchors if they are part of the same scaled configuration
        # For isolated anchors, they are their own main anchor.

